import * as THREE from 'three';
import {normalizeAssembly} from './geometry.mjs';
import {OrbitControls} from './vendor/OrbitControls.js';
import {RoomEnvironment} from './vendor/RoomEnvironment.js';
import {PAINT_GLSL,hexRGB,PAINT_INDEX,MATERIAL_INDEX} from './paint.mjs';
export async function createViewer(container,onSelect,parts){
 const canvas=document.createElement('canvas'),context=canvas.getContext('webgl2',{antialias:true,alpha:true,preserveDrawingBuffer:true,powerPreference:'high-performance'});
 if(!context)throw Error('WebGL is unavailable');
 const renderer=new THREE.WebGLRenderer({canvas,context,antialias:true,alpha:true,preserveDrawingBuffer:true});
 renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.NoToneMapping;renderer.toneMappingExposure=1;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;canvas.setAttribute('aria-label','逐件颜色与物理材质 3D 模型');container.prepend(canvas);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(31,1,.05,100);camera.position.set(6.4,3.8,6.9);
 const controls=new OrbitControls(camera,canvas);controls.target.set(0,1.7,0);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=4.8;controls.maxDistance=15;controls.maxPolarAngle=Math.PI*.54;controls.enablePan=false;controls.autoRotateSpeed=1.5;
 const pmrem=new THREE.PMREMGenerator(renderer);const room=new RoomEnvironment();const environment=pmrem.fromScene(room,.04);scene.environment=environment.texture;room.dispose();pmrem.dispose();
 scene.add(new THREE.HemisphereLight(0xffffff,0x888888,.85));const sun=new THREE.DirectionalLight(0xffffff,2.1);sun.position.set(4,8,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-4,right:4,top:6,bottom:-4,near:.1,far:20});sun.shadow.normalBias=.018;sun.shadow.bias=-.0001;sun.shadow.radius=5;scene.add(sun);const fill=new THREE.DirectionalLight(0xffffff,.65);fill.position.set(-4,3,-5);scene.add(fill);
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.ShadowMaterial({color:0x333333,opacity:.15}));ground.rotation.x=-Math.PI/2;ground.position.y=-.012;ground.receiveShadow=true;scene.add(ground);
 const [manifest,buffer]=await Promise.all([fetch('./assets/duck.json?v=2').then(r=>{if(!r.ok)throw Error('装配描述加载失败');return r.json()}),fetch('./assets/duck.bin.gz').then(async r=>{if(!r.ok)throw Error('模型网格加载失败');return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()})]);
 const geometries={};for(const [name,g]of Object.entries(manifest.geometries)){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(buffer,g.position.offset,g.position.count),3));geo.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(buffer,g.normal.offset,g.normal.count),3));geo.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,g.index.offset,g.index.count),1));geo.computeBoundingSphere();geometries[name]=geo;}
 const robot=new THREE.Group();robot.rotation.x=-Math.PI/2;const materials={},clickable=[],partById=Object.fromEntries(parts.map(p=>[p.id,p]));
 for(const item of manifest.instances){
  const p=partById[item.id],mat=new THREE.MeshPhysicalMaterial({color:0xffffff,roughness:.7,metalness:0,envMapIntensity:.5,clearcoat:0,clearcoatRoughness:.16,side:THREE.DoubleSide});
  const uniforms={uReference:{value:0},uPaintA:{value:new THREE.Vector3(1,1,1)},uPaintB:{value:new THREE.Vector3(1,1,1)},uPaintC:{value:new THREE.Vector3(1,1,1)},uPaintType:{value:0},uTextureType:{value:0},uPaintAngle:{value:90},uTextureScale:{value:1},uPartMin:{value:new THREE.Vector3(...p.bounds.min)},uPartMax:{value:new THREE.Vector3(...p.bounds.max)}};
  mat.onBeforeCompile=shader=>{Object.assign(shader.uniforms,uniforms);shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vPaintWorld;').replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvPaintWorld=(modelMatrix*vec4(transformed,1.0)).xyz;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\n'+PAINT_GLSL).replace('#include <color_fragment>','#include <color_fragment>\ndiffuseColor.rgb *= studioPaint(vPaintWorld);').replace('#include <opaque_fragment>', 'if(uReference > .5) outgoingLight = studioPaint(vPaintWorld);\n#include <opaque_fragment>\nif(uReference > .5) gl_FragColor.a = 1.0;')};
  mat.customProgramCacheKey=()=> 'microduck-material-v2';mat.userData={uniforms,style:''};materials[item.id]=mat;
  const mesh=new THREE.Mesh(geometries[item.mesh],mat);mesh.applyMatrix4(new THREE.Matrix4().fromArray(item.matrix));mesh.userData={part:item.id};mesh.castShadow=true;mesh.receiveShadow=true;robot.add(mesh);clickable.push(mesh);
 }
 scene.add(robot);normalizeAssembly(robot);
 let current={},selection=[];
 function render(){controls.update();renderer.render(scene,camera)}
 renderer.setAnimationLoop(render);
 const resize=new ResizeObserver(()=>{const r=container.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();render()});resize.observe(container);
 function setConfig(value){current=value;for(const [id,mat]of Object.entries(materials)){const a=value[id];if(!a)continue;const key=JSON.stringify(a);if(mat.userData.style===key)continue;const oldMat=mat.userData.material;mat.userData.style=key;mat.userData.material=a.material;const u=mat.userData.uniforms;u.uPaintA.value.set(...hexRGB(a.color));u.uPaintB.value.set(...hexRGB(a.color2));u.uPaintC.value.set(...hexRGB(a.color3));u.uPaintType.value=PAINT_INDEX[a.paint];u.uTextureType.value=MATERIAL_INDEX[a.material];u.uPaintAngle.value=a.angle;u.uTextureScale.value=a.scale;mat.roughness=a.roughness;mat.metalness=a.metalness;mat.clearcoat=a.clearcoat;mat.transmission=a.material==='glass'?.68:0;mat.thickness=a.material==='glass'?.13:0;mat.ior=1.48;mat.iridescence=a.material==='pearl'?.35:0;mat.sheen=a.material==='silk'?.45:0;mat.sheenColor.set(a.color);mat.sheenRoughness=.4;if(oldMat!==a.material)mat.needsUpdate=true;}render()}
 function select(ids){selection=[...ids];const chosen=new Set(ids);for(const [id,mat]of Object.entries(materials)){mat.emissive.set(0x000000);mat.emissiveIntensity=0}render()}
 let start;canvas.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!start||Math.hypot(e.clientX-start.x,e.clientY-start.y)>6)return;const r=canvas.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hits=ray.intersectObjects(clickable);if(hits.length)onSelect(hits[0].object.userData.part,{additive:e.shiftKey||e.ctrlKey||e.metaKey})});
 function view(name='hero'){const poses={hero:[6.4,3.8,6.9],front:[9.1,2.5,0],side:[0,2.5,9.1],back:[-9.1,2.5,0]};controls.autoRotate=false;camera.position.set(...(poses[name]||poses.hero));controls.target.set(0,1.7,0);controls.update();render()}
 function snapshot(value=current,w=700,h=600){const reference=Object.values(materials)[0]?.userData.uniforms.uReference.value||0,oldSelection=[...selection],before=current,position=camera.position.clone(),target=controls.target.clone(),auto=controls.autoRotate,size=renderer.getSize(new THREE.Vector2()),pixel=renderer.getPixelRatio(),aspect=camera.aspect;try{for(const mat of Object.values(materials))mat.userData.uniforms.uReference.value=0;controls.autoRotate=false;controls.enableDamping=false;camera.position.set(6.4,3.8,6.9);controls.target.set(0,1.7,0);controls.update();renderer.setPixelRatio(1);renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();select([]);setConfig(value);render();return canvas.toDataURL('image/png')}finally{for(const mat of Object.values(materials))mat.userData.uniforms.uReference.value=reference;setConfig(before);camera.position.copy(position);controls.target.copy(target);controls.update();controls.enableDamping=true;controls.autoRotate=auto;camera.aspect=aspect;camera.updateProjectionMatrix();renderer.setPixelRatio(pixel);renderer.setSize(size.x,size.y,false);select(oldSelection);render()}}
 return {ready:true,mode:'webgl',setReference(enabled){for(const mat of Object.values(materials))mat.userData.uniforms.uReference.value=enabled?1:0;render()},setConfig,select,view,snapshot,rotate(){controls.autoRotate=!controls.autoRotate;return controls.autoRotate}};
}
